ork.git\",\n    \"directory\": \"packages/dsh-annotation\"\n  },\n  \"homepage\": \"https://github.com/ECNU/EduWork/tree/main/packages/dsh-annotation#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/ECNU/EduWork/issues\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"annotation\",\n    \"eduwork\"\n  ],\n  \"publishConfig\": {\n    \"access\": \"public\"\n  }\n}\n"
